// Authored content for 3.2.8.2 Phloem and the passage of organic substances through a plant (OxfordAQA 9610 v5.1, printed
// p.25; statements 3.2.8.2.s1–s2 in data/spec.js). Official wording: "The mass flow hypothesis as an explanation of the
// mechanism of translocation in plants. Students should be able to analyse and interpret evidence from experiments related
// to the movement of water through the xylem and organic substances through phloem."
// Scope: sieve tube elements, sieve plates, companion cells and plasmodesmata are SUPPORTING (not named in the
// specification) but needed to explain the model; H⁺–sucrose co-transport is SUPPORTING detail of active loading.
// Cohesion–tension, root pressure and transpiration belong to 3.2.8.1 (cross-referenced; used here only to interpret
// xylem experiments). Aphids as vectors and feeders are 3.2.9 (the aphid stylet technique is used here only as evidence).
// Every data set on this page is ILLUSTRATIVE and labelled so; numbers come from B.phloemData / B.phloemModel
// (data/content/_phloem-art.js); the trunk-diameter and dye data are built on the shared B.plantModel.
window.BIO = window.BIO || {}; window.BIO.content = window.BIO.content || {};
(function () {
  const B = window.BIO, A = B.phloemArt, M = B.phloemModel, D = M.DATA;
  const R = "3.2.8.2";
  const S = (...n) => n.map((k) => `${R}.s${k}`);
  const P = (slot, opts) => B.views.photo(slot, opts);
  const fix = M.fix, rnd = M.round;
  const tbl = (rows, head, cls = "") => `<table class="tbl${cls ? " " + cls : ""}"><thead><tr>${head.map((h) => `<th>${h}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
  const ILL = `<span class="badge amber">illustrative data</span>`;

  // ---- numbers worked out once (and printed in the working) ----
  const TR = M.trunk();
  const narrow = M.hhmm(TR.narrowest), peakE = M.hhmm(TR.peakE);
  const ring = D.ringing.rows; // [label, unringed, ringed]
  const ringAbovePct = (100 * (ring[0][2] - ring[0][1])) / ring[0][1];
  const rootPctLower = (100 * (ring[2][1] - ring[2][2])) / ring[2][1];
  const tr = D.tracer; const speed = tr.front.dist / (tr.front.min / 60); // m h⁻¹
  const st = D.stylet; const grad = (st.pos[0][1] - st.pos[2][1]) / (st.pos[2][0] - st.pos[0][0]); // mol dm⁻³ per cm
  const exudDropPct = (100 * (st.rate[0][1] - st.rate[1][1])) / st.rate[0][1];
  const inh = D.inhibitor.groups;
  const dye = D.dye; const dyeTime = 12 / dye.bright; // minutes for 12 cm in bright light
  const dyeRatio = dye.bright / dye.dim;

  // ---- data blocks (used in the notes, the Evidence Challenge and the questions) ----
  const ringTable = () => tbl(ring.map((r) => [r[0], String(r[1]), String(r[2])]), ["Measurement after " + D.ringing.weeks + " weeks (mean of 6 plants)", "Not ringed", "Ringed"]);
  const tracerTable = () => tbl(tr.organs.map((o) => [o[0], String(o[1])]), ["Part of the plant", "Percentage of the ¹⁴C recovered"]);
  const stylet1 = () => tbl(st.pos.map((p) => [String(p[0]), fix(p[1], 2)]), ["Distance of the stylet below the leaves (cm)", "Sucrose concentration in the sap (mol dm⁻³)"]);
  const stylet2 = () => tbl(st.rate.map((r) => [r[0], fix(r[1], 1), fix(r[2], 2)]), ["Condition", "Rate of sap flow from the stylet 10 cm below the leaves (mm³ h⁻¹)", "Sucrose in the sap (mol dm⁻³)"]);
  const inhChart = (o = {}) => A.bars(inh.map((g, i) => ({ label: [["Control", "(water only)"], ["Inhibitor on", "the fed leaf"], ["Inhibitor on", "2 cm of stem"], ["Fed leaf", "kept at 2 °C"]][i], v: g[1], col: i ? "#c0610f" : "#4f8a3a" })), { yMax: 20, yTicks: [0, 5, 10, 15, 20], yLabel: "¹⁴C reaching the roots / %", title: "Percentage of the ¹⁴C reaching the roots in 3 hours after each treatment", h: 330, w: o.w });
  const trunkChart = (o = {}) => A.chart([{ name: "change in trunk diameter", pts: TR.pts.map((p) => [p.h, p.d]), col: "#1f63b5" }], { xMin: 0, xMax: 24, yMin: -160, yMax: 20, xTicks: [0, 4, 8, 12, 16, 20, 24], yTicks: [-150, -100, -50, 0], xLabel: "time of day / hours (0 = midnight)", yLabel: "change in trunk diameter / µm", zero: 0, title: "Change in the diameter of a tree trunk over one sunny day (illustrative model)", note: "illustrative model", w: o.w, h: o.h });
  const transpChart = (o = {}) => A.chart([{ name: "transpiration (model)", pts: TR.pts.map((p) => [p.h, p.E]), col: "#4f8a3a" }], { xMin: 0, xMax: 24, yMin: 0, yMax: 3.5, xTicks: [0, 4, 8, 12, 16, 20, 24], yTicks: [0, 1, 2, 3], xLabel: "time of day / hours (0 = midnight)", yLabel: "transpiration / mmol m⁻² s⁻¹", title: "Rate of transpiration from the leaves over the same day (illustrative model)", h: o.h || 280, w: o.w, note: "illustrative model" });
  const dyeTable = () => tbl([["Bright light, 50 % humidity", fix(dye.bright, 2)], ["Dim light, 50 % humidity", fix(dye.dim, 2)], ["Bright light, 90 % humidity", fix(dye.humid, 2)]], ["Condition (25 °C, gentle air movement)", "Speed of the dye front up the stem (cm min⁻¹)"]);

  const SOURCES = `<details class="tiny muted"><summary>Sources (checked 11 November 2026)</summary><p>OpenStax <em>Biology 2e</em>, <a href="https://openstax.org/books/biology-2e/pages/30-5-transport-of-water-and-solutes-in-plants" target="_blank" rel="noopener">§30.5 Transport of Water and Solutes in Plants</a> (sources and sinks; seeds, tubers and bulbs can be either; intermediate leaves send products both ways; active loading with a sucrose–H⁺ symporter; water enters from the xylem by osmosis; unloading by diffusion or active transport; sap up to about 30 % sugar; xylem tension about −2 MPa at the leaf). Kimball's <em>Biology</em>, LibreTexts <a href="https://bio.libretexts.org/Bookshelves/Introductory_and_General_Biology/Biology_(Kimball)/16%3A_The_Anatomy_and_Physiology_of_Plants/16.02%3A_Plant_Physiology/16.2B%3A_Phloem" target="_blank" rel="noopener">§16.2B Phloem</a> (girdling: carbohydrate accumulates above the ring and the roots starve; aphid stylets: sap exudes under pressure after the aphid is cut away; autoradiography shows labelled products in the phloem; higher osmotic pressure in leaves than in sinks; translocation stops when phloem cells are killed; up to about 100 cm per hour). S. Saupe, CSB/SJU Plant Physiology lecture notes, <a href="https://faculty.csbsju.edu/SSAUPE/biol327/Lecture/phloem.htm" target="_blank" rel="noopener">Phloem transport</a> (Malpighi's girdling experiments, 1675; the aphid stylet technique of Kennedy and Mittler, 1953; sieve tube pressure 0.1 to 2.5 MPa measured with stylets; average speed about 30 cm per hour; ¹⁴CO₂ labelling; transport in opposite directions in neighbouring sieve tubes; callose at sieve pores; respiratory inhibitors block loading). Edaphic Scientific, <a href="https://edaphic.com.au/?p=5328" target="_blank" rel="noopener">dendrometer application note</a> (stem diameter largest around sunrise, smallest around the middle of the afternoon; a maximum daily shrinkage of 0.4 mm in olive). Every data table and graph on this page is <strong>illustrative</strong>: invented to show the pattern these experiments found, not real measurements.</p></details>`;

  // ============================== Interactive 1: Phloem Translocation Explorer ==============================
  const explorer = { kind: "phloemExplorer", title: "Phloem Translocation Explorer",
    note: "Choose a source and a sink to see which way phloem sap (orange) and xylem water (blue) move. Then step through the six stages of the mass flow model, or ring the stem to remove the phloem.",
    questions: [
      { id: `q-${R}-iv1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Choose the lower mature leaf as the source and the root tips as the sink. Which describes the movement in the stem between them?", options: ["Phloem sap moves down the stem; water in the xylem moves up", "Phloem sap and xylem water both move down", "Phloem sap and xylem water both move up", "Phloem sap moves up; water in the xylem moves down"], answer: 0, explanation: "Phloem sap moves from source to sink, here downwards. Xylem water always moves up the plant in the transpiration stream, so in this part of the stem the two flows are in opposite directions." },
      { id: `q-${R}-iv2`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Choose the storage organ as the source. When is a storage organ a source, and why?", options: ["In spring: its stored starch is hydrolysed to sugars, and sucrose is loaded into the phloem and carried to the growing shoot", "In summer: it photosynthesises faster than the leaves", "In autumn: it is filling with starch", "At all times: storage organs are always sources"], answer: 0, explanation: "Before the new leaves can photosynthesise enough, the plant uses its stored starch. The same organ is a sink in summer and autumn, when sucrose arrives and is stored as starch." },
      { id: `q-${R}-iv3`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "Ring the stem. Choose the upper mature leaf as the source and the storage organ as the sink. What happens?", options: ["Phloem sap reaches the ring but cannot pass it, so sugars build up above the ring; water still moves up in the xylem", "The sap is diverted into the xylem and reaches the storage organ that way", "Both the xylem and the phloem stop working", "Nothing changes, because the storage organ is below the soil"], answer: 0, explanation: "Removing a ring of bark removes the phloem but leaves the xylem in the wood, so water still reaches the leaves but sugars cannot pass the ring." },
      { id: `q-${R}-iv4`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Step through the model. What makes the hydrostatic pressure rise at the source end of the sieve tube?", options: ["Water entering the sieve tube elements by osmosis after sucrose has been loaded", "Sucrose molecules pressing on the sieve plates", "The companion cells contracting", "Transpiration pulling water up the xylem"], answer: 0, explanation: "Loading sucrose lowers the water potential of the sap, so water enters by osmosis (mostly from the xylem). The extra volume in a tube with fairly rigid walls raises the hydrostatic pressure." },
    ] };

  // ============================== Interactive 2: Experimental Evidence Challenge ==============================
  const evidence = { kind: "phloemEvidence", title: "Experimental Evidence Challenge",
    note: "Six investigations: four on phloem and two on xylem. For each, read the method and the results, then answer the questions. Your answers count towards mastery. All the data are illustrative: they are invented to show the pattern the real experiments found (the real findings and sources are summarised for each one).",
    items: [
      { key: "ringing", tissue: "phloem", title: "Ringing a woody stem",
        method: "Young woody plants of the same species and size were used. On six plants a ring of bark 2 cm wide was removed from the stem, 30 cm below the lowest leaves, leaving the wood in place. Six plants were not ringed. All were grown in the same conditions for four weeks.",
        data: () => ringTable(),
        real: "Real finding: when bark is ringed, carbohydrate accumulates in the bark above the ring, the bark there swells, and the roots eventually starve; the leaves do not wilt (Malpighi, 1675; Kimball §16.2B).",
        questions: [
          { id: `q-${R}-ev1`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Which conclusion is best supported by these data?", options: ["Sugars move down the stem in the bark, which contains the phloem, and the ring stops them", "Sugars move down the stem in the xylem", "Ringing increases photosynthesis in the leaves", "The roots make the sugars they need"], answer: 0, explanation: `After four weeks the bark above the ring had more sucrose in ringed plants than in unringed plants (${ring[0][2]} v ${ring[0][1]} mg g⁻¹), and the bark below the ring had less (${ring[1][2]} v ${ring[1][1]} mg g⁻¹); the roots of ringed plants hardly grew. The wood (xylem) was intact, so the sugars must normally travel in the tissue that was removed: the phloem.` },
          { id: `q-${R}-ev2`, ref: R, stmts: S(2), type: "short", marks: 3, stem: "Use the data to explain (a) why the sucrose concentration above the ring rose, (b) why the roots of ringed plants gained so little mass, and (c) why no leaves wilted. (3 marks)", scheme: [{ point: "(a) Sucrose from the leaves moving down in the phloem cannot cross the ring, so it accumulates above it", marks: 1 }, { point: "(b) Little sucrose reaches the roots, so less respiration and growth / no sugars to build new cells", marks: 1 }, { point: "(c) The xylem (wood) was not removed, so water still reaches the leaves", marks: 1 }], model: `(a) Sucrose made in the leaves is translocated down the stem in the phloem, which is in the bark. The ring removed the phloem, so sucrose arriving from above cannot pass and builds up (${ring[0][1]} rising to ${ring[0][2]} mg g⁻¹). (b) Below the ring almost no sucrose arrives (${ring[1][2]} mg g⁻¹), so root cells have little sugar for respiration and for making new cell walls, and the roots grew only ${fix(ring[2][2], 1)} g instead of ${fix(ring[2][1], 1)} g. (c) The wood, which contains the xylem, was left in place, so water and mineral ions still move up to the leaves and they stay turgid.`, commonErrors: "Saying the xylem was removed; saying sugars move up from the roots." },
        ] },
      { key: "tracer", tissue: "phloem", title: "Radioactive tracer and autoradiograph",
        method: `A mature leaf halfway up the stem was given carbon dioxide containing radioactive ¹⁴C (¹⁴CO₂) for 20 minutes in the light. The ¹⁴C is fixed into sugars by photosynthesis. Three hours later the plant was cut into parts and the radioactivity of each part measured. A section of the stem below the leaf was placed on photographic film in the dark (autoradiography). In a second plant the tracer was first detected ${fix(tr.front.dist, 1)} m below the fed leaf ${tr.front.min} minutes after feeding.`,
        data: () => tracerTable() + `<div class="row" style="flex-wrap:wrap;gap:.5rem;justify-content:center;margin-top:.5rem"><div style="flex:1 1 260px;max-width:380px">${A.autorad({ panel: "section", title: "Stem section (illustrative drawing)" })}</div><div style="flex:1 1 260px;max-width:380px">${A.autorad({ panel: "film", title: "Autoradiograph of the same section (illustrative drawing)" })}</div></div>`,
        real: "Real finding: after a leaf is given ¹⁴CO₂, labelled sugars appear in the phloem (dark only over the phloem on autoradiographs) and travel both up to shoot tips and down to roots; leaves halfway up a stem export in both directions (Saupe; OpenStax §30.5; Kimball §16.2B).",
        questions: [
          { id: `q-${R}-ev3`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "Why do the upper mature leaves contain almost none of the ¹⁴C?", options: ["They are sources themselves, so they export sugars rather than import them", "The xylem carried all the ¹⁴C down to the roots", "Substances in the phloem can move only downwards", "Mature leaves have no phloem"], answer: 0, explanation: "Mature leaves make more sugar than they use, so they are sources. Sinks (shoot tip, roots, stem tissues) receive the labelled sugar." },
          { id: `q-${R}-ev4`, ref: R, stmts: S(2), type: "gap", marks: 1, stem: `The tracer was first detected ${fix(tr.front.dist, 1)} m below the fed leaf after ${tr.front.min} minutes. Calculate the speed of translocation.`, text: "Speed = {{1}} m h⁻¹", answers: { 1: [fix(speed, 1), fix(speed, 2)] }, explanation: `${tr.front.min} min = ${fix(tr.front.min / 60, 2)} h. Speed = ${fix(tr.front.dist, 1)} ÷ ${fix(tr.front.min / 60, 2)} = ${fix(speed, 1)} m h⁻¹. This is a minimum: the tracer front may have passed that point a little before it was detected.` },
          { id: `q-${R}-ev5`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "The autoradiograph is dark only over the phloem. What does this show?", options: ["Organic substances made in the leaf are carried in the phloem, not the xylem", "Phloem cells carry out photosynthesis", "The xylem contains ¹⁴CO₂ gas", "Radioactivity kills phloem cells"], answer: 0, explanation: "The ¹⁴C was fixed into sugars in the leaf; where the film is darkened, those labelled organic substances were present in the stem: only in the phloem." },
        ] },
      { key: "stylet", tissue: "phloem", title: "Aphid stylets and phloem sap",
        method: "Aphids feeding on a willow stem were anaesthetised with carbon dioxide and their bodies cut away, leaving each stylet in one sieve tube element. Sap oozing from the cut stylets was collected for one hour and its sucrose concentration measured, at three distances below the leaves. Then the leaves were shaded for six hours and the stylet 10 cm below the leaves was sampled again.",
        data: () => stylet1() + stylet2(),
        real: "Real finding: sap keeps exuding from severed stylets for hours, so sieve tube contents are under pressure (measured at 0.1 to 2.5 MPa); sap is mostly sucrose solution, and its concentration is higher near sources than near sinks (Kennedy and Mittler, 1953; Saupe; Kimball §16.2B).",
        questions: [
          { id: `q-${R}-ev6`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "Sap kept flowing out of each cut stylet for hours without the aphid. Which part of the mass flow hypothesis does this support?", options: ["The sap in sieve tubes is under a high hydrostatic pressure", "Sucrose is unloaded at the sinks", "Water enters the sieve tubes from the xylem", "Companion cells contain many mitochondria"], answer: 0, explanation: "Nothing is sucking: the sap is pushed out by the pressure inside the sieve tube, as the hypothesis predicts." },
          { id: `q-${R}-ev7`, ref: R, stmts: S(1, 2), type: "short", marks: 3, stem: "Explain how the sucrose concentrations at different distances, and the effect of shading the leaves, support the mass flow hypothesis. (3 marks)", scheme: [{ point: "Sucrose concentration falls with distance from the leaves (source) towards the sink: a concentration gradient as the hypothesis predicts", marks: 1 }, { point: "Shading reduces photosynthesis, so less sucrose is made and loaded at the source", marks: 1 }, { point: "So the water potential falls less, less water enters by osmosis, the pressure is lower and the sap flows more slowly", marks: 1 }], model: `The sucrose concentration falls from ${fix(st.pos[0][1], 2)} mol dm⁻³ at ${st.pos[0][0]} cm below the leaves to ${fix(st.pos[2][1], 2)} mol dm⁻³ at ${st.pos[2][0]} cm, so there is a concentration gradient from source to sink, as the hypothesis predicts. When the leaves are shaded they photosynthesise less, so less sucrose is loaded into the sieve tubes (the sap concentration fell to ${fix(st.rate[1][2], 2)} mol dm⁻³). The water potential of the sap at the source is therefore not lowered as much, less water enters by osmosis, the hydrostatic pressure is lower and the sap flows more slowly (${fix(st.rate[0][1], 1)} to ${fix(st.rate[1][1], 1)} mm³ h⁻¹).`, commonErrors: "Saying the aphid sucks the sap; describing the numbers without linking them to pressure." },
        ] },
      { key: "inhibitor", tissue: "phloem", title: "Metabolic inhibitors and cooling",
        method: "Each plant was given ¹⁴CO₂ on one mature leaf for 20 minutes. Then one treatment was applied: water only (control); a respiratory inhibitor painted on the fed leaf; the same inhibitor applied to a 2 cm length of stem between the leaf and the roots; or the fed leaf kept at 2 °C. After 3 hours the ¹⁴C in the roots was measured. Five plants per treatment.",
        data: () => inhChart({ w: 440 }),
        real: "Real finding: respiratory inhibitors, lack of oxygen and cold block loading at the source and stop translocation; killing phloem cells stops it altogether (Saupe; Kimball §16.2B). Treating only a length of the transport path usually has a smaller effect.",
        questions: [
          { id: `q-${R}-ev8`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Why was the ¹⁴CO₂ given BEFORE the treatments were applied?", options: ["So the labelled sugar had already been made, and any difference shows an effect on transport, not on photosynthesis", "Because the inhibitor only works when ¹⁴C is present", "So that the plants could recover from the inhibitor", "To increase the amount of ATP in the leaf"], answer: 0, explanation: "An inhibitor or cold could also reduce photosynthesis. Labelling first separates the two effects." },
          { id: `q-${R}-ev9`, ref: R, stmts: S(1, 2), type: "short", marks: 3, stem: "Evaluate what these results show about whether translocation needs energy from respiration. (3 marks)", scheme: [{ point: `Inhibitor on the fed leaf (${inh[1][1]} %) or cooling the leaf (${inh[3][1]} %) greatly reduces export compared with the control (${inh[0][1]} %): loading at the source needs ATP from respiration (active)`, marks: 1 }, { point: `Inhibitor on the stem has a much smaller effect (${inh[2][1]} %): flow along the sieve tubes is mainly passive, as the mass flow hypothesis predicts`, marks: 1 }, { point: "The small fall with the stem treatment may be because living sieve tube elements and companion cells need some ATP (to stay alive / reload sucrose that leaks out), or the inhibitor spread", marks: 1 }, { point: "Conclusions are tentative: only five plants per group and no measure of spread; the inhibitor on the leaf may also have reduced sucrose synthesis in the mesophyll, not only loading; only the roots were sampled, so total export was not measured", marks: 1 }], alternatives: "Maximum 3 marks.", model: `Painting the inhibitor on the fed leaf cut the ¹⁴C reaching the roots from ${inh[0][1]} % to ${inh[1][1]} %, and cooling the leaf to ${inh[3][1]} %, so the source needs ATP from respiration to export sugar: this supports active loading by companion cells. The same inhibitor on a length of stem had a much smaller effect (${inh[2][1]} %), which fits the idea that flow along the sieve tube is driven by a pressure difference and is mainly passive. The small fall could mean living sieve tube elements need some ATP, for example to reload sucrose that leaks out, or that some inhibitor spread to other tissues. The conclusions are tentative: there were only five plants in each group and no measure of spread, the inhibitor on the leaf may also have reduced the conversion of labelled products of photosynthesis into sucrose rather than only loading, and only the roots were sampled, so less ¹⁴C in the roots does not show that total export from the leaf fell.`, commonErrors: "Concluding that the whole of translocation is active transport." },
        ] },
      { key: "trunk", tissue: "xylem", title: "Tree trunk diameter over a day",
        method: "A dendrometer (a very sensitive gauge clamped round a tree trunk) recorded the change in trunk diameter every 15 minutes over one sunny day with moist soil. The rate of transpiration from the leaves was estimated for the same day.",
        data: () => trunkChart({ w: 460, h: 320 }) + transpChart({ w: 460, h: 280 }),
        real: "Real finding: trunks and stems are widest around sunrise and narrowest around the middle of the afternoon, shrinking by tens to hundreds of micrometres (Edaphic Scientific; 0.4 mm in olive). These graphs come from the page's illustrative plant model.",
        questions: [
          { id: `q-${R}-ev10`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "At about what time is the trunk narrowest, and why?", options: [`About ${narrow}, soon after transpiration is fastest and the water in the xylem is under the greatest tension`, "About 04:00, when the plant is respiring and using water", "About 12:00 exactly, because the Sun is highest", "About 20:00, when the stomata close"], answer: 0, explanation: `In the model transpiration peaks at about ${peakE} and the trunk is narrowest at about ${narrow}. Water is pulled out of the xylem faster than it enters from the roots, so the tension rises and pulls the vessel walls inwards. Water stored in the trunk tissues delays the response a little.` },
          { id: `q-${R}-ev11`, ref: R, stmts: S(2), type: "short", marks: 3, stem: "Explain how these results support the idea that water in the xylem is pulled up by transpiration (cohesion–tension, 3.2.8.1). (3 marks)", scheme: [{ point: "Trunk diameter decreases as transpiration increases (and is smallest soon after its peak)", marks: 1 }, { point: "Water is pulled up the xylem faster than it enters / water column under tension (negative pressure)", marks: 1 }, { point: "Cohesion between water molecules and adhesion to the vessel walls pull the walls inwards, so the trunk narrows; it recovers at night when transpiration stops", marks: 1 }], model: `The trunk shrinks during the day while transpiration is high, reaching its smallest diameter about ${M.fix(TR.narrowest - TR.peakE, 1).replace(/\.0$/, "")} hours after transpiration is fastest, and swells again at night when transpiration stops. If water were pushed up from below the xylem would be under positive pressure and the trunk would swell. Instead the shrinkage shows that the water column is under tension: water evaporating from the leaves pulls the column up, the water molecules stick together by cohesion and to the xylem walls by adhesion, and the tension pulls the walls of the xylem vessels inwards and draws water out of the living tissues of the bark into the xylem.`, commonErrors: "Saying the trunk shrinks because it loses water by transpiration from the bark." },
        ] },
      { key: "dye", tissue: "xylem", title: "Dye moving up a leafy shoot",
        method: "Leafy shoots were cut under water and stood in a dilute solution of a red dye. The position of the dye front was measured through the stem, and cross-sections were cut to see which tissue was stained. Three conditions, five shoots each.",
        data: () => dyeTable() + `<p class="small">Cross-sections: only the xylem was stained red. A shoot with a ring of bark removed took up the dye at the same speed.</p>`,
        real: "Real finding: dyes such as eosin travel up the xylem of cut shoots, faster when transpiration is faster. These speeds come from the page's illustrative plant model (bright light set at 0.9 cm min⁻¹).",
        questions: [
          { id: `q-${R}-ev12`, ref: R, stmts: S(2), type: "gap", marks: 1, stem: "Use the table. How long would the dye front take to rise 12 cm in bright light at 50 % humidity? Give your answer to the nearest minute.", text: "Time = {{1}} minutes", answers: { 1: [fix(dyeTime, 0)] }, explanation: `Time = distance ÷ speed = 12 ÷ ${fix(dye.bright, 2)} = ${fix(dyeTime, 1)} min, which is ${fix(dyeTime, 0)} minutes to the nearest minute.` },
          { id: `q-${R}-ev13`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Which conclusion do the dye results support best?", options: ["Water moves up through the xylem, and faster when transpiration is faster", "Water moves up through the phloem", "Light makes water move by active transport in the xylem", "Ringing the stem stops water reaching the leaves"], answer: 0, explanation: `Only the xylem was stained, ringing made no difference, and the dye moved ${fix(dyeRatio, 1)} times faster in bright light than in dim light and much more slowly in humid air: the conditions that increase transpiration increase the speed.` },
        ] },
    ] };

  // ============================== notes ==============================
  const compareTable = tbl([
    ["What moves", "Water and mineral ions", "Sucrose, amino acids and other organic substances (assimilates), dissolved in water"],
    ["Direction", "Up the plant, from roots to leaves", "From sources to sinks: up or down, and in different directions in different sieve tubes at the same time"],
    ["Cells", "Xylem vessels: dead, no cytoplasm, no end walls, lignified walls", "Sieve tube elements: living, thin layer of cytoplasm, no nucleus, sieve plates; each with a companion cell"],
    ["Driving force", "Mainly transpiration pull (tension, negative pressure); also root pressure (3.2.8.1)", "Hydrostatic pressure difference between source and sink (positive pressure)"],
    ["Energy from the plant", "Not needed for the flow itself (evaporation is powered by the Sun's heat); root pressure needs active transport of ions", "ATP needed to load sucrose at the source; the flow itself is passive"],
    ["Pressure in the tube", "Usually below atmospheric pressure (tension)", "Above atmospheric pressure: sap oozes out when a sieve tube is cut"],
  ], ["", "Xylem", "Phloem"]);

  window.BIO.content[R] = {
    status: "draft",
    keywords: ["phloem", "translocation", "mass flow", "pressure flow", "Münch", "source", "sink", "sucrose", "assimilate", "sieve tube", "sieve tube element", "sieve plate", "companion cell", "plasmodesmata", "loading", "unloading", "co-transport", "proton pump", "hydrostatic pressure", "water potential", "ringing", "girdling", "radioactive tracer", "14C", "autoradiograph", "autoradiography", "aphid stylet", "metabolic inhibitor", "dendrometer", "trunk diameter", "dye", "xylem"],
    notes: () => `
<div class="notice"><strong>What the specification requires (3.2.8.2).</strong> The <strong>mass flow hypothesis</strong> as an explanation of the mechanism of <strong>translocation</strong>; and you must be able to <strong>analyse and interpret evidence from experiments</strong> on the movement of <strong>water through the xylem</strong> and of <strong>organic substances through the phloem</strong>. The structure of sieve tube elements and companion cells is not named in the specification, but you need it to explain the model, so it is taught here as supporting. How water enters roots and moves up the xylem is <a href="#/topic/3.2.8.1">3.2.8.1</a>. <span class="badge teal">required</span> <span class="badge">supporting</span></div>

<h2 data-stmt="${R}.s1">1. Translocation: from sources to sinks <span class="badge teal">required</span></h2>
<p><strong>Translocation</strong> is the movement of <strong>organic substances</strong> (assimilates) through the <strong>phloem</strong>, from where they are made or released to where they are used or stored. The main substance translocated is <strong>sucrose</strong>, dissolved in water; phloem sap also carries amino acids, some mineral ions and plant hormones. Sucrose is a good transport sugar: it is soluble, and it is non-reducing, so it is chemically unreactive on the way (<a href="#/topic/3.1.1.2">3.1.1.2</a>).</p>
<ul><li>A <strong>source</strong> is a part of the plant that <strong>releases</strong> sugars into the phloem: mainly <strong>mature leaves</strong> photosynthesising in the light, and <strong>storage organs</strong> when their stored starch is being used.</li>
<li>A <strong>sink</strong> is a part of the plant that <strong>takes sugars out</strong> of the phloem, to use them in respiration and growth or to store them: <strong>growing leaves and shoot tips, root tips, flowers, developing fruits and seeds</strong>, and <strong>storage organs</strong> while they are filling.</li></ul>
<p>Organs <strong>can change roles</strong>. A potato tuber is a <strong>sink</strong> in summer, while it fills with starch; the next <strong>spring</strong> the starch is hydrolysed to sugars and the sprouting tuber becomes a <strong>source</strong> for the new shoots, until their leaves can photosynthesise enough. A young leaf is a sink while it grows, and becomes a source when it is mature. Because sources and sinks can be above or below each other, phloem sap moves <strong>up or down</strong>; a leaf halfway up a stem can send sugars both up to the shoot tip and down to the roots, in different sieve tubes.</p>

<h2 data-stmt="${R}.s1">2. Phloem structure <span class="badge">supporting</span></h2>
<p>Phloem is a tissue made of several cell types. The two you need are the sieve tube elements and their companion cells.</p>
${P("phloem-ts")}
${P("phloem-ls")}
<ul><li><strong>Sieve tube elements</strong> are long living cells joined <strong>end to end</strong> to form <strong>sieve tubes</strong>. When they mature they lose their nucleus, vacuole and most organelles, leaving only a thin layer of cytoplasm against the cell wall, so there is a wide, open channel for sap.</li>
<li>The end walls between them are <strong>sieve plates</strong>: walls perforated by <strong>sieve pores</strong>, so sap can flow from one element to the next.</li>
<li>Each sieve tube element has a <strong>companion cell</strong> beside it, with dense cytoplasm, a large <strong>nucleus</strong>, many <strong>ribosomes</strong> and many <strong>mitochondria</strong>. The companion cell carries out the metabolism the sieve tube element cannot, and its mitochondria supply the <strong>ATP for active loading</strong> of sucrose.</li>
<li>Each companion cell is joined to its sieve tube element by many <strong>plasmodesmata</strong>: channels through the cell walls lined with cell surface membrane, joining the cytoplasm of the two cells, so sucrose and other substances can pass between them.</li></ul>
<p class="small muted">In the micrographs above, the large, empty-looking cells are sieve tube elements; the small, densely stained cells pressed against them are companion cells. Magnifications are the photographer's; there is no scale bar, so you cannot measure cell sizes from these images.</p>
<p>The diagram shows how a companion cell is joined to its sieve tube element.</p>

<h2 data-stmt="${R}.s1">3. The mass flow hypothesis step by step <span class="badge teal">required</span></h2>
<p>The <strong>mass flow hypothesis</strong> (also called the pressure flow hypothesis, first proposed by Ernst Münch in 1930) explains translocation as the flow of a <strong>whole solution</strong> along the sieve tubes, pushed by a difference in <strong>hydrostatic pressure</strong> between the source and the sink. <strong>Mass flow</strong> means the bulk movement of a fluid, with everything dissolved in it, from a region of higher pressure to a region of lower pressure. The six steps below match the numbered stages of the Mass flow model in the explorer.</p>
<ol><li><strong>Loading at the source.</strong> Companion cells <strong>actively transport</strong> sucrose into the sieve tube elements, using ATP (details in section 4).</li>
<li><strong>Water enters.</strong> The high sucrose concentration <strong>lowers the water potential</strong> of the sap in the sieve tube elements below that of the nearby xylem and surrounding cells, so <strong>water enters by osmosis</strong>, mostly from the <strong>xylem</strong>.</li>
<li><strong>High pressure at the source.</strong> The extra water raises the <strong>hydrostatic pressure</strong> inside the sieve tube elements at the source end.</li>
<li><strong>Mass flow.</strong> The sap flows along the sieve tubes, through the sieve pores, <strong>from the high pressure at the source to the lower pressure at the sink</strong>, carrying the sucrose and other dissolved substances with it.</li>
<li><strong>Unloading at the sink.</strong> Sucrose is removed from the sieve tubes into the sink cells, by <strong>diffusion</strong> or <strong>active transport</strong>. There it is used in <strong>respiration</strong>, used to make new cells (for example cellulose for cell walls), or converted to <strong>starch</strong> for storage. Using or storing it keeps the sucrose concentration in the sink cells low, so sucrose keeps moving out of the phloem.</li>
<li><strong>Water leaves at the sink.</strong> With less sucrose, the <strong>water potential</strong> of the sap rises, so <strong>water leaves by osmosis</strong> into the sink cells and the xylem. The hydrostatic pressure at the sink end stays <strong>lower</strong>, so the pressure gradient is kept.</li></ol>
<p>Notice that the flow is driven by a difference in <strong>hydrostatic pressure</strong>, and that <strong>energy is used only at the ends</strong> (for loading, and sometimes unloading). The flow along the tube itself is <strong>passive</strong>. Most of the water that enters at the source comes from the xylem and returns to it at the sink, so water circulates between the two tissues. Measured pressures in sieve tubes are about 0.1 to 2.5 MPa (for comparison, a car tyre is about 0.2 MPa), and sap typically travels about 0.3 m per hour, up to about 1 m per hour.</p>
<p>Use the explorer to change the source and the sink: the direction of flow in the phloem changes, but water in the xylem always moves up.</p>

<h2 data-stmt="${R}.s1">4. Active loading at the source <span class="badge">supporting</span></h2>
<p>Sucrose is loaded into companion cells and sieve tube elements <strong>against its concentration gradient</strong>, so it needs <strong>active transport</strong>. In many plants this works by <strong>co-transport</strong> (active transport <a href="#/topic/3.1.4.3">3.1.4.3</a>; co-transport with sodium ions in the ileum <a href="#/topic/3.2.2.3">3.2.2.3</a>):</p>
<ol><li>Sucrose made in mesophyll cells moves towards the phloem and passes into the cell walls next to the companion cells.</li>
<li>A <strong>proton pump</strong> in the companion cell's cell surface membrane uses <strong>ATP</strong> (from its many mitochondria) to pump <strong>hydrogen ions (H⁺) out</strong> of the cell, so the H⁺ concentration becomes higher outside than inside.</li>
<li>H⁺ ions diffuse back in through a <strong>co-transporter protein</strong>, down their concentration gradient, and the protein carries <strong>sucrose in with them</strong>, against the sucrose concentration gradient.</li>
<li>Sucrose then diffuses from the companion cell into the sieve tube element through the <strong>plasmodesmata</strong>.</li></ol>
<p class="small"><span class="badge">stretch</span> Some plants load sucrose without crossing a membrane from the cell wall; you do not need the alternative routes.</p>

<h2 data-stmt="${R}.s1 ${R}.s2">5. A hypothesis: what the model assumes and predicts <span class="badge teal">required</span></h2>
<p>Mass flow is a <strong>hypothesis</strong>: a model that explains the evidence well, not something that has been seen directly. It is widely accepted, but parts of it are still tested. Keep three things separate when you write about it.</p>
<table class="tbl"><thead><tr><th>Type of statement</th><th>Examples</th></tr></thead><tbody>
<tr><td><strong>Observations</strong> (evidence)</td><td>Sap oozes from cut sieve tubes and from cut aphid stylets; sap is mostly sucrose solution; it is more concentrated nearer sources; ringing stops sugars passing; ¹⁴C from a leaf appears in the phloem and reaches sinks; inhibitors at the source stop export.</td></tr>
<tr><td><strong>Assumptions</strong> of the model</td><td>The sieve pores are open in a living plant, so sap can flow through the sieve plates; the cell surface membranes of sieve tube elements are partially permeable, so osmosis happens; loading at the source and unloading at the sink keep a concentration difference; within one sieve tube, everything moves together in one direction at the same speed.</td></tr>
<tr><td><strong>Predictions</strong> that can be tested</td><td>Sap should be under pressure, higher at the source than at the sink; sucrose concentration should fall from source to sink; stopping loading (cold, inhibitors, darkness) should stop flow; all solutes in one sieve tube should move at the same speed.</td></tr></tbody></table>
<p>Most predictions are confirmed; the last assumption is the hardest to test and is where the doubts lie (section 7).</p>

<h2 data-stmt="${R}.s2 ${R}.s1">6. Evidence for the mass flow hypothesis <span class="badge teal">required</span></h2>
<p><strong>Ringing (girdling).</strong> A ring of bark, which contains the phloem, is removed from a woody stem, leaving the wood (xylem). Over the following weeks the bark <strong>just above the ring swells</strong> and its sugar concentration rises, tissues below the ring receive no sugars and the roots eventually die. The leaves do not wilt. This shows that sugars move <strong>down in the phloem</strong>, and that water moves <strong>up in the xylem</strong>.</p>
<p><strong>Radioactive tracers and autoradiography.</strong> A leaf is given carbon dioxide containing radioactive carbon-14 (<strong>¹⁴CO₂</strong>). Photosynthesis fixes the ¹⁴C into sugars. After a time, sections of the stem are placed on photographic film in the dark: the radiation darkens the film, making an <strong>autoradiograph</strong>. The dark areas lie over the <strong>phloem</strong>, so the labelled organic substances travel in the phloem. Measuring how far the label has travelled in a given time gives the speed; and labelled sugar is found in sinks both above and below the fed leaf.</p>
<p><strong>Aphid stylets.</strong> Aphids feed by pushing their fine mouthparts (stylets) into a single sieve tube element (<a href="#/topic/3.2.9.2">3.2.9.2</a>). If a feeding aphid is anaesthetised and its body cut away, <strong>sap keeps oozing</strong> from the cut stylet for hours. This shows the sap is <strong>under pressure</strong>, and it gives pure sap to analyse: it is mostly <strong>sucrose solution</strong>. Stylets at different positions show that the sucrose concentration (and the pressure) is <strong>higher near sources than near sinks</strong>.</p>
<ul><li><strong>Concentration gradient.</strong> Sucrose concentration in the phloem is higher in leaves than in sinks, as the hypothesis predicts; when leaves are shaded, the concentration and the rate of flow fall.</li>
<li><strong>Metabolic inhibitors.</strong> Respiratory inhibitors, lack of oxygen or cooling applied to the <strong>source</strong> stop translocation, showing that loading needs <strong>ATP</strong>, as the model requires. Killing the phloem cells stops translocation completely: the hypothesis needs living sieve tube elements with partially permeable membranes. Inhibitors applied only to a length of stem have a smaller effect, which fits a mainly passive flow along the tube.</li>
<li><strong>Speed.</strong> Translocation is far too fast to be diffusion: sucrose would take years to diffuse a metre, but in a sieve tube it travels that far in an hour or two.</li></ul>
<p class="small"><span class="badge">supporting</span> Each piece of evidence supports one part of the model. Ringing and tracers show <em>where</em> organic substances move; stylets show the sap is <em>under pressure</em> and has a <em>concentration gradient</em>; inhibitors show where <em>energy</em> is needed.</p>

<h2 data-stmt="${R}.s1 ${R}.s2">7. Observations the hypothesis does not fully explain <span class="badge">exam skill: evaluation</span></h2>
<ul><li><strong>Sieve plates resist flow.</strong> The sieve plates lie across the path of the sap and should slow mass flow. If mass flow is the only mechanism, why are they there? <span class="badge">supporting</span> In prepared samples the pores are often blocked by callose and protein, which the plant deposits within seconds of damage, so the pores may be more open in an intact living plant than they look under the microscope; measuring flow without damaging the tube is very difficult.</li>
<li><strong>Different solutes move at different speeds.</strong> In mass flow everything in one sieve tube should move together, but sucrose and amino acids have sometimes been found to travel at different rates.</li>
<li><strong>Movement in both directions at once.</strong> Substances can move up and down the same stem at the same time. Mass flow can explain this only if the flows are in <strong>different sieve tubes</strong>; flow in two directions in one sieve tube would contradict it.</li>
<li><strong>Energy along the path.</strong> Some scientists argued that, if the flow is purely physical, poisons applied to the stem should have no effect, yet they slow it a little. Supporters answer that sieve tube elements are living cells that need some ATP to stay alive and to reload sucrose that leaks out.</li></ul>
<p>None of these disproves the hypothesis, but they show it may be incomplete. In an exam, describe the evidence, say which part of the model it supports or challenges, and use "suggests" or "supports", not "proves".</p>

<h2 data-stmt="${R}.s2">8. Analysing experiments on xylem and phloem <span class="badge teal">required</span></h2>
<p>You may be given results from any experiment on water movement in the xylem or organic substances in the phloem. Work through the same steps each time.</p>
<ol><li><strong>Identify the variables.</strong> What was changed (independent variable), what was measured (dependent variable), and what was kept the same. Is there a <strong>control</strong> (for example unringed plants, or a treatment with water only)?</li>
<li><strong>Describe the pattern</strong> with figures from the data, including units: "rose from ... to ...".</li>
<li><strong>Explain</strong> the pattern using the model: which tissue, which direction, which driving force.</li>
<li><strong>Evaluate.</strong> Number of repeats, variation, whether the method could have damaged the tissue, whether another variable could explain the result (for example, an inhibitor may also reduce photosynthesis), and whether the data show a correlation or a cause.</li></ol>
<p><strong>Experiments on water in the xylem</strong> (interpret them using <a href="#/topic/3.2.8.1">3.2.8.1</a>):</p>
<ul><li><strong>Dyes.</strong> A cut shoot stood in a coloured dye: cross-sections show the dye only in the <strong>xylem</strong>, and the dye rises faster in conditions that increase transpiration (bright light, dry or moving air).</li>
<li><strong>Trunk diameter.</strong> A sensitive gauge round a tree trunk shows it is <strong>narrowest around the middle of the afternoon</strong>, when transpiration is fastest, and widest around dawn. <span class="badge">supporting</span> This supports cohesion–tension: water is pulled up under <strong>tension</strong>, which pulls the xylem walls inwards and draws water out of the living tissues of the bark.</li>
<li><strong>Cutting a stem.</strong> When the xylem of a transpiring plant is cut, water does not spurt out; instead air is drawn in. The water was under tension, not pushed up from below. By contrast, a cut <strong>phloem</strong> oozes sap, because it is under positive pressure.</li>
<li><strong>Root pressure.</strong> Sap exudes from a stump cut close to the soil, especially at night; a respiratory inhibitor in the soil water stops it, because root pressure depends on active transport of mineral ions into the xylem (<a href="#/topic/3.2.8.1">3.2.8.1</a>).</li>
<li><strong>Ringing</strong> answers a xylem question too: leaves above a ring do not wilt, so water is not carried in the bark.</li></ul>
<p>The graph below comes from this page's illustrative plant model, built on the same model used for transpiration in 3.2.8.1. The trunk diameter is smallest about ${M.fix(TR.narrowest - TR.peakE, 1).replace(/\.0$/, "")} hours after transpiration peaks, because water stored in the trunk tissues is drawn on first.</p>
<p>Try the Evidence Challenge to practise interpreting all six kinds of experiment.</p>

<h2 data-stmt="${R}.s1 ${R}.s2">9. Xylem and phloem compared <span class="badge teal">required</span></h2>
${compareTable}
<p class="small">Comparison questions want <strong>matched pairs</strong>: give the xylem feature and the phloem feature for the same point ("xylem carries water up, phloem carries sucrose up or down"), not two separate lists.</p>

<h2 data-stmt="${R}.s1 ${R}.s2">10. Common misconceptions <span class="badge teal">required</span></h2>
<ul><li><strong>"Phloem carries sugar down and xylem carries water up."</strong> Xylem water does move up, but phloem sap moves from <em>source to sink</em>, up or down.</li>
<li><strong>"Translocation is active transport along the phloem."</strong> Energy is used to <em>load</em> sucrose at the source (and sometimes to unload it). The flow along the sieve tube is passive mass flow down a pressure gradient.</li>
<li><strong>"Sucrose diffuses through the phloem."</strong> Diffusion is far too slow; the whole solution flows.</li>
<li><strong>"Water moves into the sieve tube because of the high pressure."</strong> It is the other way round: water enters by osmosis because the water potential is low, and that raises the pressure.</li>
<li><strong>"Sap flows down the water potential gradient."</strong> Mass flow is down a <em>hydrostatic pressure</em> gradient. Water enters and leaves the sieve tubes by osmosis, down water potential gradients.</li>
<li><strong>"Sieve tube elements are dead, like xylem vessels."</strong> They are living (with a cell surface membrane and a thin layer of cytoplasm) but have no nucleus; they rely on their companion cells.</li>
<li><strong>"Aphids suck up phloem sap."</strong> The sap is under pressure and is forced into the aphid; a cut stylet goes on oozing without the aphid.</li>
<li><strong>"A leaf is always a source."</strong> Young growing leaves are sinks; a storage organ is a sink in summer and a source in spring.</li></ul>
${SOURCES}`,
    diagrams: [
      { id: `d-${R}-1`, title: "Structure of phloem", status: "draft", caption: "Left: longitudinal section of two sieve tube elements joined end to end by a sieve plate, each with a companion cell joined to it by plasmodesmata. Right: a sieve plate seen face-on, with its sieve pores, and a transverse section of a sieve tube element with its smaller companion cell. Schematic, not to scale.", alt: "Diagram. Left, a tall pale orange tube made of two cells stacked end to end, separated by a dashed cross-wall labelled sieve plate (end wall with pores). Each cell is labelled sieve tube element and has only a thin layer of cytoplasm lining the wall, with no nucleus and no vacuole. Beside each is a narrow, densely dotted companion cell with a large purple nucleus and many small mitochondria. Small channels through the shared wall are labelled plasmodesmata. Right, a brown disc with round holes labelled sieve pores, shown as a sieve plate seen face-on; below it a large circle labelled sieve tube element with a small circle beside it labelled companion cell.", svg: A.structure() },
      { id: `d-${R}-4`, title: "Active loading of sucrose (supporting)", status: "draft", caption: "A proton pump in the companion cell membrane uses ATP to pump H⁺ out into the cell wall. H⁺ diffuses back in through a co-transporter, carrying sucrose in against its concentration gradient. Sucrose then passes through plasmodesmata into the sieve tube element, lowering the water potential of the sap. One common route; schematic.", alt: "Diagram with four regions from left to right: a green mesophyll or phloem parenchyma cell, a hatched cell wall region, a large companion cell and a sieve tube element. In the companion cell membrane, a red proton pump with an arrow carrying H⁺ out into the wall, labelled ATP to ADP plus Pi, with a mitochondrion. Below, an orange co-transporter with arrows carrying H⁺ and sucrose into the companion cell together. Orange arrows carry sucrose from the companion cell through two plasmodesmata into the sieve tube element.", svg: A.loading() },
      { id: `d-${R}-5`, title: "A ringing experiment", status: "draft", caption: "A ring of bark (containing the phloem) is removed, leaving the wood (xylem). Sap moving down in the phloem cannot pass the ring, so sugars accumulate and the bark swells above it; tissues below receive no sugars. Water still moves up in the xylem, so the leaves stay turgid. Ringing works on woody stems, where the phloem is in the bark and the xylem is in the wood. Illustration: Biology Lab; labels added.", alt: "Two drawings of a cut woody stem with leaves near the top. In both, a band of bark has been removed part way down, exposing pale wood. Orange arrows in the bark point down and stop just above the ring; a blue dashed arrow runs up the middle of the stem from the bottom to the top, through the ring. Left, labelled just after ringing: labels say sap moves down in the phloem, bark contains the phloem, bark removed so the phloem is cut and the wood (xylem) is left in place, and water moves up in the xylem through the ring. Right, labelled some weeks later: the bark just above the ring has swollen into a large bulge, labelled bark swells above the ring, sugars accumulate here; below the ring no sugars arrive and the roots eventually starve; the leaves stay turgid because water still reaches them in the xylem.", svg: A.ringing() },
      { id: `d-${R}-6`, title: "Radioactive tracer and autoradiograph", status: "draft", caption: "Left: transverse section of a stem with a ring of vascular bundles, each with xylem (blue, inner) and phloem (orange, outer). Right: the autoradiograph of the same section after a leaf above was given ¹⁴CO₂: the film is darkened only over the phloem. Illustrative drawing, not a real autoradiograph.", alt: "Left, a circle representing a stem section with a pale central pith and eight vascular bundles in a ring; each bundle has a blue circle of xylem on the inside and an orange oval of phloem on the outside. Right, a grey square of film with a faint dashed circle and eight dark ovals in exactly the positions of the phloem, and no dark marks where the xylem is.", svg: A.autorad() },
      { id: `d-${R}-7`, title: "Using aphid stylets", status: "draft", caption: "(a) An aphid's stylets pass between cells into a single sieve tube element; the sap is forced in by its own pressure. (b) With the aphid removed and the stylets cut, sap keeps oozing from the cut end for hours and can be collected and analysed. In (b) the aphid has been removed from the same picture and the cut stylets and drop of sap are drawn on. Illustration: Biology Lab; labels added.", alt: "Two copies of the same leaf section side by side. (a) A green aphid stands on the upper epidermis; its dark stylets wind down between the mesophyll cells, past the empty xylem vessels, and end inside a sieve tube element in the phloem. An orange band along the stylets with arrowheads pointing up towards the aphid shows sap forced up the stylets by its own pressure. (b) The aphid has gone; a short cut stylet sticks up from the leaf surface with a drop of sap on its end, labelled drop of phloem sap, keeps flowing out for hours, collected with a fine glass tube. The stylets are still in the sieve tube element, whose sap is under pressure.", svg: A.aphid() },
      { id: `d-${R}-8`, title: "Trunk diameter over a day (illustrative)", status: "draft", caption: `Illustrative model, not a measurement: change in trunk diameter of a tree on a sunny day with moist soil, from this page's model built on the shared transpiration model. The trunk is widest before dawn and narrowest at about ${narrow}, soon after transpiration peaks (about ${peakE}); it shrinks by ${fix(TR.maxShrink, 0)} µm and recovers overnight. Real trunks show the same pattern.`, alt: `Line graph. The x-axis is time of day from 0 to 24 hours; the y-axis is change in trunk diameter from 0 down to minus 150 micrometres. The line is close to 0 from midnight to about 06:00, falls steadily through the morning to a minimum of minus 150 at about ${narrow}, then rises steeply in the evening and levels off near 0 by midnight.`, svg: trunkChart() },
    ],
    interactives: [explorer, evidence],
    focus: [
      { slot: "phloem-ts", title: "Reading a phloem micrograph", ref: R, caption: "Transverse section of phloem in a pumpkin (Cucurbita) stem, photographed at ×400 (no scale bar).",
        explanation: () => `<p>Pumpkin stems are a favourite for looking at phloem because their sieve tube elements are unusually wide. In a transverse section the sieve tube elements are the large, almost empty-looking cells: most of their contents were lost as they matured, leaving a thin layer of cytoplasm against the wall and no nucleus. The much smaller, densely stained cells pressed against them are companion cells, full of cytoplasm, with a nucleus. Occasionally the knife cuts exactly through a sieve plate, which then appears as a disc or a ring across a sieve tube element. The photographer gives the magnification as ×400, but there is no scale bar, so the actual size of the cells cannot be worked out from this image.</p>`,
        question: { id: `q-${R}-fx1`, ref: R, stmts: S(1), type: "short", marks: 3, stem: "A student looking at this micrograph says the large empty cells must be dead, like xylem vessels. Explain why she is wrong, and why the companion cells look so densely stained. (3 marks)", scheme: [{ point: "Sieve tube elements are living: they keep a cell surface membrane and a thin layer of cytoplasm (needed for osmosis / to stay partially permeable)", marks: 1 }, { point: "They look empty because they have lost their nucleus, vacuole and most organelles, leaving an open channel for sap", marks: 1 }, { point: "Companion cells have dense cytoplasm with a nucleus, many ribosomes and mitochondria (to supply ATP for loading / carry out metabolism for the sieve tube element)", marks: 1 }], model: "Sieve tube elements are living cells: they keep a cell surface membrane and a thin layer of cytoplasm, so their membrane is partially permeable and water can enter them by osmosis. They look empty because, as they mature, they lose their nucleus, vacuole and most organelles, leaving a wide channel for the sap to flow through. The companion cells are densely stained because they are full of cytoplasm with a nucleus, many ribosomes and many mitochondria: they carry out the metabolism the sieve tube elements cannot and supply the ATP for loading sucrose.", commonErrors: "Saying sieve tube elements have no cytoplasm at all." } },
    ],
    examFocus: `<ul>
<li><strong>Describe mass flow in order.</strong> Loading (active, companion cells) → water potential falls → water enters by osmosis from the xylem → high hydrostatic pressure at the source → mass flow to the sink → unloading → water potential rises, water leaves → lower pressure at the sink. Name the place (source or sink) in each step.</li>
<li><strong>Use the right gradient.</strong> Water moves by osmosis down a <em>water potential</em> gradient; sap moves by mass flow down a <em>hydrostatic pressure</em> gradient.</li>
<li><strong>Energy.</strong> Say where it is used: active loading at the source (ATP from the companion cells' mitochondria). Do not call the whole of translocation active transport.</li>
<li><strong>Evidence questions.</strong> State the observation, then link it to one part of the model: aphid sap oozing → pressure; ringing → sugars travel in the phloem; ¹⁴C autoradiograph → organic substances in the phloem; inhibitors at the source → loading needs ATP; higher concentration near sources → gradient.</li>
<li><strong>Against the hypothesis.</strong> Sieve plates resisting flow; different solutes at different speeds; two-way movement (explained only if in different sieve tubes). Say "suggests", not "proves".</li>
<li><strong>Xylem experiments.</strong> Dyes in the xylem; trunk narrowest in the afternoon (tension); air drawn in when xylem is cut; leaves above a ring do not wilt.</li>
<li><strong>Data.</strong> Quote figures with units; calculate speeds (distance ÷ time, convert minutes to hours), percentage changes and gradients; look for the control and comment on repeats.</li>
<li><strong>Scope.</strong> Sieve tube and companion cell structure and co-transport are supporting knowledge you use to explain the model; root structure, root pressure and transpiration are in 3.2.8.1; aphids as vectors are in 3.2.9.</li></ul>`,
    synoptic: [
      { ref: "3.2.8.1", text: "Water and mineral ions in the xylem: root pressure, transpiration and the cohesion–tension explanation used to interpret xylem experiments." },
      { ref: "3.1.4.2", text: "Water potential and osmosis explain why water enters sieve tubes at the source and leaves at the sink." },
      { ref: "3.1.4.3", text: "Active transport (carrier proteins and ATP) explains why loading sucrose against its concentration gradient needs energy." },
      { ref: "3.2.2.3", text: "Co-transport in the ileum (sodium ions with glucose) is the same principle as the proton–sucrose co-transport used in phloem loading." },
      { ref: "3.1.1.2", text: "Sucrose is the translocated sugar: soluble and non-reducing; starch is the storage form in sinks." },
      { ref: "3.2.9.2", text: "Aphids insert stylets into sieve tubes; the sap is under high pressure and is forced into the aphid's gut." },
      { ref: "3.1.2.1", text: "Plasmodesmata, mitochondria and ribosomes in companion cells; the loss of organelles in sieve tube elements." },
    ],
    quickCheck: [
      { id: `q-${R}-qc1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "What is translocation?", options: ["The movement of organic substances such as sucrose through the phloem, from sources to sinks", "The movement of water from the roots to the leaves in the xylem", "The loss of water vapour from the leaves", "The active uptake of mineral ions by root hair cells"], answer: 0, explanation: "Translocation is the transport of assimilates in the phloem." },
      { id: `q-${R}-qc2`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "In a potato plant in summer, which of these is a sink?", options: ["A tuber that is filling with starch", "A mature leaf photosynthesising in bright light", "A sprouting tuber in spring", "A xylem vessel in the stem"], answer: 0, explanation: "A filling tuber takes sucrose out of the phloem and stores it as starch. A sprouting tuber in spring is a source." },
      { id: `q-${R}-qc3`, ref: R, stmts: S(1), type: "gap", marks: 3, stem: "Complete the sentence about the source end of a sieve tube.", text: "Loading sucrose lowers the water potential of the sap, so water enters from the {{1}} by {{2}}, raising the {{3}} pressure.", answers: { 1: ["xylem"], 2: ["osmosis"], 3: ["hydrostatic", "turgor"] }, explanation: "Xylem; osmosis; hydrostatic (turgor) pressure." },
      { id: `q-${R}-qc4`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Sap keeps flowing from a cut aphid stylet for hours. What does this show?", options: ["The contents of sieve tubes are under pressure", "Aphids actively pump sap from the phloem", "Sieve tubes contain only water", "The contents of the xylem are under tension"], answer: 0, explanation: "Without the aphid, only pressure inside the sieve tube can push the sap out." },
      { id: `q-${R}-qc5`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "A ring of bark is removed from a tree trunk. Why do the leaves above the ring not wilt?", options: ["The xylem, in the wood, is not removed, so water still moves up", "Sugars accumulate above the ring", "The phloem carries water to the leaves", "Transpiration stops"], answer: 0, explanation: "Ringing removes the phloem (in the bark) but leaves the xylem." },
    ],
    flashcards: [
      { id: `f-${R}-1`, front: "Translocation.", back: "Movement of organic substances (mainly sucrose, also amino acids) in the phloem, from sources to sinks." },
      { id: `f-${R}-2`, front: "Source (with examples).", back: "Part of a plant that releases sugars into the phloem: mature leaves in the light; a storage organ when its starch is used (e.g. a tuber in spring)." },
      { id: `f-${R}-3`, front: "Sink (with examples).", back: "Part of a plant that removes sugars from the phloem to use or store them: shoot tips, growing leaves, root tips, fruits, seeds, filling storage organs." },
      { id: `f-${R}-4`, front: "How can a storage organ change role?", back: "Sink while filling with starch (summer); source when starch is hydrolysed and sucrose loaded for new shoots (spring)." },
      { id: `f-${R}-5`, front: "Why is sucrose the transported sugar?", back: "Soluble, and non-reducing, so it is chemically unreactive on the way." },
      { id: `f-${R}-6`, front: "Sieve tube element (supporting).", back: "Living cell, joined end to end with others; thin layer of cytoplasm; no nucleus or vacuole; end walls are sieve plates." },
      { id: `f-${R}-7`, front: "Sieve plate (supporting).", back: "End wall between sieve tube elements, perforated by sieve pores, so sap can pass." },
      { id: `f-${R}-8`, front: "Companion cell (supporting).", back: "Beside each sieve tube element; dense cytoplasm, nucleus, many mitochondria and ribosomes; supplies ATP for active loading." },
      { id: `f-${R}-9`, front: "Plasmodesmata in phloem (supporting).", back: "Channels through the walls joining companion cell and sieve tube element cytoplasm; sucrose passes through them." },
      { id: `f-${R}-10`, front: "Mass flow: what happens at the source?", back: "Sucrose actively loaded; water potential falls; water enters by osmosis from the xylem; hydrostatic pressure rises." },
      { id: `f-${R}-11`, front: "Mass flow: what happens at the sink?", back: "Sucrose unloaded and used or stored; water potential of the sap rises; water leaves by osmosis; pressure stays lower." },
      { id: `f-${R}-12`, front: "What drives the flow of sap along a sieve tube?", back: "A difference in hydrostatic pressure: high at the source, lower at the sink. The flow itself is passive." },
      { id: `f-${R}-13`, front: "Where is ATP used in translocation?", back: "Loading sucrose at the source (and sometimes unloading at the sink), supplied by companion cell mitochondria." },
      { id: `f-${R}-14`, front: "Co-transport loading (supporting).", back: "Proton pump uses ATP to pump H⁺ out; H⁺ diffuses back in through a co-transporter, carrying sucrose in against its gradient." },
      { id: `f-${R}-15`, front: "Ringing: method and finding.", back: "Remove a ring of bark (phloem), leave the wood. Sugars build up and bark swells above the ring; roots starve; leaves do not wilt." },
      { id: `f-${R}-16`, front: "¹⁴CO₂ and autoradiography.", back: "¹⁴C fixed into sugars in a leaf; film darkens only over the phloem; label reaches sinks; distance ÷ time gives speed." },
      { id: `f-${R}-17`, front: "Aphid stylet evidence.", back: "Cut stylet keeps oozing sap: sieve tube contents under pressure; sap is mostly sucrose, more concentrated near sources." },
      { id: `f-${R}-18`, front: "Metabolic inhibitors and translocation.", back: "At the source they stop export: loading needs ATP. On a stretch of stem they have a smaller effect: flow is mainly passive." },
      { id: `f-${R}-19`, front: "Observations mass flow does not fully explain.", back: "Sieve plates resist flow; different solutes at different speeds; two-way movement (only possible in different sieve tubes)." },
      { id: `f-${R}-20`, front: "Why is mass flow called a hypothesis?", back: "It is a model that explains most evidence but has not been seen directly, and some observations do not fit it fully." },
      { id: `f-${R}-21`, front: "Trunk diameter evidence (xylem).", back: "Narrowest in mid-afternoon when transpiration is fastest: water in the xylem is under tension, pulling the walls in." },
      { id: `f-${R}-22`, front: "Dye evidence (xylem).", back: "Dye in a cut shoot stains only the xylem and rises faster when transpiration is faster." },
      { id: `f-${R}-23`, front: "Xylem v phloem: direction and pressure.", back: "Xylem: water up, under tension. Phloem: sap source to sink (up or down), under positive pressure." },
      { id: `f-${R}-24`, front: "Xylem v phloem: cells.", back: "Xylem vessels dead, lignified, no end walls. Sieve tube elements living, no nucleus, sieve plates, companion cells." },
    ],
    questions: [
      // ---- MCQ ----
      { id: `q-${R}-m1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "What is the main role of a companion cell in translocation? (supporting structure)", options: ["To supply ATP for the active loading of sucrose into the sieve tube element", "To form the sieve plates", "To carry water up the stem", "To store starch for the sieve tube element"], answer: 0, explanation: "Companion cells have many mitochondria; their ATP powers loading." },
      { id: `q-${R}-m2`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Which feature of a mature sieve tube element makes mass flow easier?", options: ["It has lost its nucleus and most organelles, leaving a wide open channel", "Its walls are thickened with lignin", "It has a large central vacuole", "It has no cell surface membrane"], answer: 0, explanation: "Few contents means little resistance to flow; it keeps its membrane, which is needed for osmosis." },
      { id: `q-${R}-m3`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Why does water enter the sieve tube elements at a source?", options: ["Loading sucrose lowers the water potential of the sap below that of the xylem", "The hydrostatic pressure in the sieve tube is lower than in the xylem", "Water is actively transported in by companion cells", "Transpiration pulls water into the sieve tube"], answer: 0, explanation: "Water moves by osmosis from higher to lower water potential." },
      { id: `q-${R}-m4`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "According to the mass flow hypothesis, where is the hydrostatic pressure in a sieve tube highest?", options: ["At the source", "At the sink", "Halfway between the source and the sink", "It is the same all along the tube"], answer: 0, explanation: "Water entering at the source raises the pressure; it is lower at the sink where water leaves." },
      { id: `q-${R}-m5`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "In spring a daffodil bulb produces new leaves before they can photosynthesise. Which statement is correct?", options: ["The bulb is a source and the growing leaves are sinks", "The bulb is a sink and the growing leaves are sources", "Both are sources", "Both are sinks"], answer: 0, explanation: "The bulb's stored food is loaded into the phloem and carried to the growing leaves." },
      { id: `q-${R}-m6`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "Which observation is hardest to explain by the mass flow hypothesis?", options: ["Two different solutes in the same sieve tube moving at different speeds", "Sap oozing from a cut aphid stylet", "A higher sucrose concentration in the phloem near the leaves than near the roots", "Sugars accumulating above a ring of removed bark"], answer: 0, explanation: "In mass flow the whole solution moves together, so all solutes in one tube should move at the same speed. The other three are evidence for the hypothesis." },
      { id: `q-${R}-m7`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "In a tracer experiment, why is carbon dioxide containing ¹⁴C supplied to a leaf?", options: ["The ¹⁴C is fixed into sugars by photosynthesis, so the sugars can be traced as they move", "¹⁴C speeds up translocation", "The phloem can only carry radioactive substances", "¹⁴CO₂ dissolves in the xylem water and labels it"], answer: 0, explanation: "Radioactive carbon becomes part of the organic products of photosynthesis." },
      { id: `q-${R}-m8`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Which result would show that water, not sugar, moves in the xylem?", options: ["A dye taken up by a cut shoot stains only the xylem, and ringing the bark does not slow it", "Sugars accumulate above a ring of removed bark", "Sap oozes from a cut sieve tube", "¹⁴C from a leaf darkens film over the phloem"], answer: 0, explanation: "The dye follows the water; the other three are phloem evidence." },
      { id: `q-${R}-m9`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "A tree trunk is narrowest in the middle of the afternoon. Which explanation is best?", options: ["Transpiration is fastest, so the water in the xylem is under the greatest tension, pulling the walls inwards", "The phloem is under the highest pressure", "The tree respires fastest at that time", "Root pressure is highest in the afternoon"], answer: 0, explanation: "Tension (negative pressure) in the xylem pulls the walls in; at night they recover." },
      { id: `q-${R}-m10`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "A respiratory inhibitor applied to a source leaf stops the export of sugars. What does this suggest?", options: ["Loading sucrose into the phloem needs ATP from respiration", "Mass flow along the sieve tubes needs ATP at every sieve plate", "Sucrose moves by diffusion", "The xylem needs ATP to move water"], answer: 0, explanation: "The model requires active loading at the source; the flow along the tube is passive." },
      { id: `q-${R}-m11`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "How does sucrose enter a companion cell against its concentration gradient? (supporting)", options: ["By co-transport with hydrogen ions that move down their gradient", "By osmosis", "By simple diffusion through the membrane", "By mass flow from the xylem"], answer: 0, explanation: "A proton pump (using ATP) makes the H⁺ gradient; H⁺ flowing back in carries sucrose with it." },
      { id: `q-${R}-m12`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "Which comparison of xylem and phloem is correct?", options: ["Xylem contents are usually under tension; phloem contents are under positive pressure", "Xylem carries sucrose; phloem carries water only", "Both are made of dead cells", "Both move their contents only upwards"], answer: 0, explanation: "That is why air is drawn into cut xylem but sap oozes from cut phloem." },
      // ---- gap ----
      { id: `q-${R}-g1`, ref: R, stmts: S(1), type: "gap", marks: 4, stem: "Complete the passage about the sink end of a sieve tube.", text: "At a sink, sucrose is {{1}} from the sieve tube and used in respiration or converted to {{2}} for storage. This makes the water potential of the sap {{3}}, so water leaves by osmosis and the hydrostatic pressure is {{4}} than at the source.", answers: { 1: ["unloaded", "removed", "actively transported", "transported"], 2: ["starch"], 3: ["higher", "rise", "increase", "less negative"], 4: ["lower", "less"] }, explanation: "Unloaded; starch; higher (less negative); lower." },
      { id: `q-${R}-g2`, ref: R, stmts: S(2), type: "gap", marks: 2, stem: `Ringing data. Sucrose in the bark above the ring site: ${ring[0][1]} mg g⁻¹ in unringed plants, ${ring[0][2]} mg g⁻¹ in ringed plants (illustrative).`, text: "Percentage increase = {{1}} % (to the nearest whole number). This shows sucrose was moving {{2}} the stem in the bark.", answers: { 1: [fix(ringAbovePct, 0)], 2: ["down", "downwards", "down through"] }, explanation: `(${ring[0][2]} − ${ring[0][1]}) ÷ ${ring[0][1]} × 100 = ${fix(ringAbovePct, 1)} %, so ${fix(ringAbovePct, 0)} %. It built up above the ring, so it was moving down.` },
      // ---- match ----
      { id: `q-${R}-mt1`, ref: R, stmts: S(2), type: "match", marks: 4, stem: "Match each observation to the conclusion it best supports.", pairs: [{ left: "Sap oozes from a cut aphid stylet for hours", right: "Sieve tube contents are under pressure" }, { left: "Bark swells above a ring of removed bark", right: "Sugars move down the stem in the phloem" }, { left: "Leaves above a ring of removed bark do not wilt", right: "Water moves up in the xylem" }, { left: "A respiratory inhibitor on a source leaf stops export", right: "Loading needs ATP" }] },
      { id: `q-${R}-mt2`, ref: R, stmts: S(1), type: "match", marks: 4, stem: "Match each structure to its role in translocation.", pairs: [{ left: "Sieve plate", right: "Lets sap pass from one sieve tube element to the next" }, { left: "Companion cell", right: "Supplies ATP for active loading" }, { left: "Plasmodesmata", right: "Let sucrose pass from the companion cell into the sieve tube element" }, { left: "Xylem vessel", right: "Supplies the water that enters the sieve tube at the source" }] },
      // ---- sequence ----
      { id: `q-${R}-sq1`, ref: R, stmts: S(1), type: "sequence", marks: 4, stem: "Put the stages of the mass flow hypothesis in order, starting at the source.", steps: ["Companion cells actively load sucrose into sieve tube elements", "The water potential of the sap falls", "Water enters from the xylem by osmosis", "Hydrostatic pressure rises at the source", "Sap flows by mass flow towards the sink", "Sucrose is unloaded and used or stored at the sink", "Water leaves the sieve tube at the sink by osmosis"], explanation: "Loading → lower water potential → osmosis → high pressure → mass flow → unloading → water leaves." },
      // ---- label ----
      { id: `q-${R}-lb1`, ref: R, stmts: S(1), type: "label", marks: 6, drag: true, stem: "The diagram shows phloem in longitudinal section. Identify each numbered structure.", svg: A.structure({ numbers: { ste: 1, plate: 2, pd: 3, cc: 4, nuc: 5, mito: 6 }, title: "Phloem in longitudinal section with numbered structures" }), labels: [{ n: 1, answer: "Sieve tube element" }, { n: 2, answer: "Sieve plate" }, { n: 3, answer: "Plasmodesmata" }, { n: 4, answer: "Companion cell" }, { n: 5, answer: "Nucleus" }, { n: 6, answer: "Mitochondrion" }], bank: ["Sieve tube element", "Sieve plate", "Plasmodesmata", "Companion cell", "Nucleus", "Mitochondrion", "Xylem vessel", "Vacuole", "Chloroplast", "Lignin thickening"], explanation: "1 the wide sieve tube element (no nucleus); 2 the sieve plate across its end; 3 plasmodesmata through the shared wall; 4 the companion cell; 5 its nucleus; 6 one of its many mitochondria." },
      // ---- data and calculations ----
      { id: `q-${R}-c1`, ref: R, stmts: S(2), type: "short", marks: 2, stem: `In a tracer experiment (illustrative data), ¹⁴C from a fed leaf was first detected ${fix(tr.front.dist, 1)} m away after ${tr.front.min} minutes. Calculate the speed of translocation in m h⁻¹ and suggest why the true speed may be higher. (2 marks)`, scheme: [{ point: `${fix(tr.front.dist, 1)} ÷ ${fix(tr.front.min / 60, 2)} = ${fix(speed, 1)} m h⁻¹`, marks: 1 }, { point: "The label may have arrived before it was first detected / sampling intervals / time for ¹⁴C to be fixed and loaded is included", marks: 1 }], model: `${tr.front.min} minutes = ${fix(tr.front.min / 60, 2)} hours, so speed = ${fix(tr.front.dist, 1)} ÷ ${fix(tr.front.min / 60, 2)} = ${fix(speed, 1)} m h⁻¹. The true speed may be higher because the time includes the time taken to fix the ¹⁴C into sugar and load it, and the label may have passed that point before it was first measured.`, commonErrors: `Dividing by 45 and giving ${fix(tr.front.dist / tr.front.min, 3)} without converting to hours.` },
      { id: `q-${R}-d1`, ref: R, stmts: S(1, 2), type: "short", marks: 4, stem: `Data (illustrative). Sap from severed aphid stylets on one stem:${stylet1()}(a) Calculate the mean change in sucrose concentration per cm between 10 cm and 90 cm. (1 mark) (b) Explain how these results support the mass flow hypothesis. (3 marks)`, scheme: [{ point: `(a) (${fix(st.pos[0][1], 2)} − ${fix(st.pos[2][1], 2)}) ÷ ${st.pos[2][0] - st.pos[0][0]} = ${fix(grad, 3)} mol dm⁻³ per cm (a fall)`, marks: 1 }, { point: "(b) Concentration is highest nearest the leaves (source) and falls towards the sink: a gradient", marks: 1 }, { point: "(b) High concentration at the source gives low water potential, water entering by osmosis and high hydrostatic pressure", marks: 1 }, { point: "(b) Lower concentration towards the sink as sucrose is unloaded: lower pressure, so sap flows down the pressure gradient", marks: 1 }], model: `(a) (${fix(st.pos[0][1], 2)} − ${fix(st.pos[2][1], 2)}) ÷ ${st.pos[2][0] - st.pos[0][0]} = ${fix(grad, 3)} mol dm⁻³ per cm. (b) The sucrose concentration is highest near the leaves, the source, and falls with distance towards the sink, as the hypothesis predicts. A high concentration at the source lowers the water potential, so water enters by osmosis and the hydrostatic pressure there is high. Where sucrose is unloaded at the sink, the concentration and so the pressure are lower, so the sap flows down this pressure gradient from source to sink.`, commonErrors: "Describing the gradient without linking it to pressure." },
      { id: `q-${R}-d2`, ref: R, stmts: S(2), type: "short", marks: 4, stem: `Data (illustrative model). ${trunkChart()}(a) Describe the change in trunk diameter between 06:00 and 24:00. (2 marks) (b) Explain why the trunk is narrowest in the afternoon. (2 marks)`, scheme: [{ point: `(a) Decreases from about 06:00 to a minimum of about −150 µm at about ${narrow}`, marks: 1 }, { point: "(a) Then increases, quickly in the evening, back towards its starting diameter by midnight", marks: 1 }, { point: "(b) Transpiration is fastest in the afternoon (high light and temperature, low humidity)", marks: 1 }, { point: "(b) Water in the xylem is under tension; cohesion and adhesion pull the vessel walls inwards", marks: 1 }], model: `(a) The diameter stays almost constant until about 06:00, then decreases through the morning to a minimum about 150 µm smaller at about ${narrow}. It then increases, most quickly in the early evening, and has almost returned to its starting value by midnight. (b) In the afternoon light intensity and temperature are high and humidity low, so transpiration is fastest. Water is pulled up the xylem faster than it enters, so the water column is under tension; because the water molecules stick to each other (cohesion) and to the xylem walls (adhesion), the tension pulls the walls inwards and the trunk narrows.`, commonErrors: "Quoting the time of the Sun's highest point instead of reading the graph." },
      { id: `q-${R}-d3`, ref: R, stmts: S(1, 2), type: "short", marks: 3, stem: `Data (illustrative). ${inhChart()}Each plant was given ¹⁴CO₂ on one leaf before the treatment. Use the results to explain where energy is used in translocation. (3 marks)`, scheme: [{ point: `Inhibitor on the fed leaf reduces ¹⁴C reaching the roots from ${inh[0][1]} % to ${inh[1][1]} % (cooling the leaf: ${inh[3][1]} %)`, marks: 1 }, { point: "So ATP from respiration is needed at the source, to load sucrose actively (companion cells)", marks: 1 }, { point: `Inhibitor on the stem has a much smaller effect (${inh[2][1]} %), so flow along the sieve tube is mainly passive (mass flow)`, marks: 1 }], model: `When the respiratory inhibitor was put on the fed leaf only ${inh[1][1]} % of the ¹⁴C reached the roots, compared with ${inh[0][1]} % in the control, and cooling the leaf had a similar effect (${inh[3][1]} %). Energy from respiration is therefore needed at the source, where companion cells load sucrose by active transport. The same inhibitor on a length of stem reduced it only to ${inh[2][1]} %, so the flow along the sieve tube is mainly passive, driven by the pressure difference, as the mass flow hypothesis says.`, commonErrors: "Saying the results prove translocation is active transport." },
      // ---- short answer and evaluation ----
      { id: `q-${R}-s1`, ref: R, stmts: S(1), type: "short", marks: 4, stem: "Explain how a difference in hydrostatic pressure develops between the source and the sink ends of a sieve tube. (4 marks)", scheme: [{ point: "Sucrose is actively loaded at the source (by companion cells, using ATP)", marks: 1 }, { point: "This lowers the water potential of the sap, so water enters by osmosis (from the xylem), raising the hydrostatic pressure at the source", marks: 1 }, { point: "At the sink sucrose is unloaded and used in respiration or stored as starch", marks: 1 }, { point: "The water potential of the sap rises, water leaves by osmosis, so the pressure at the sink is lower", marks: 1 }], model: "At the source, companion cells use ATP to load sucrose actively into the sieve tube elements. This lowers the water potential of the sap, so water moves in by osmosis from the nearby xylem, and the hydrostatic pressure rises. At the sink, sucrose is unloaded into the sink cells, where it is used in respiration or converted to starch. Removing sucrose raises the water potential of the sap, so water leaves by osmosis and the hydrostatic pressure there stays lower. The result is a pressure gradient from source to sink.", commonErrors: "Saying the pressure itself draws water in; missing the sink end." },
      { id: `q-${R}-s2`, ref: R, stmts: S(1, 2), type: "short", marks: 4, stem: "Mass flow is described as a hypothesis. Give two observations that support it and two that it does not fully explain. (4 marks)", scheme: [{ point: "Support: sap oozes from cut aphid stylets / sieve tubes, so it is under pressure", marks: 1 }, { point: "Support: sucrose concentration higher near the source than the sink / ringing causes accumulation above the ring / ¹⁴C tracer found in phloem and sinks / inhibitors at the source stop translocation (any one other)", marks: 1 }, { point: "Not explained: sieve plates would resist mass flow / different solutes move at different speeds", marks: 1 }, { point: "Not explained: movement in both directions at the same time (only possible in different sieve tubes) / some effect of inhibitors along the path", marks: 1 }], model: "Supporting: sap oozes from the cut stylets of aphids for hours, showing that sieve tube contents are under pressure; and the sucrose concentration in the phloem is higher near sources than near sinks, as the model predicts. Not fully explained: sieve plates lie across the path of the sap and should resist mass flow; and different solutes have been found moving at different speeds, whereas in mass flow everything in a sieve tube should move together.", commonErrors: "Giving two pieces of supporting evidence that both show the same thing (pressure)." },
      { id: `q-${R}-s3`, ref: R, stmts: S(1, 2), type: "short", marks: 4, stem: "Compare the transport of water in the xylem with the transport of sucrose in the phloem. Give four matched differences. (4 marks)", scheme: [{ point: "Direction: xylem only upwards; phloem source to sink, up or down", marks: 1 }, { point: "Pressure: xylem contents usually under tension (negative pressure); phloem under positive (hydrostatic) pressure", marks: 1 }, { point: "Cells: xylem vessels dead (lignified, no end walls); sieve tube elements living (no nucleus, sieve plates, companion cells)", marks: 1 }, { point: "Energy: xylem flow needs no ATP from the plant (evaporation / transpiration pull); phloem needs ATP for active loading at the source", marks: 1 }, { point: "Substances: xylem water and mineral ions; phloem sucrose, amino acids (organic substances) in solution", marks: 1 }], alternatives: "Maximum 4 marks. Each mark needs both halves of the comparison.", model: "Xylem moves water only upwards, from roots to leaves, but phloem moves sap from sources to sinks, up or down. Water in the xylem is usually under tension, while phloem sap is under positive hydrostatic pressure. Xylem vessels are dead, lignified tubes with no end walls, whereas sieve tube elements are living cells without a nucleus, with sieve plates and companion cells. Movement in the xylem needs no ATP from the plant because it is driven by evaporation from the leaves, but phloem transport needs ATP to load sucrose at the source.", commonErrors: "Writing two separate lists with no matched points." },
      { id: `q-${R}-s4`, ref: R, stmts: S(2), type: "short", marks: 3, stem: "A student says the ringing experiment proves that sugars travel in the phloem. Evaluate this claim. (3 marks)", scheme: [{ point: "Supports it: sugars accumulate above the ring and do not reach the roots when the bark (with the phloem) is removed, while the xylem is intact", marks: 1 }, { point: "But the bark contains other tissues too (cortex, epidermis), so ringing alone does not show it is the phloem", marks: 1 }, { point: "Tracer / autoradiograph evidence showing ¹⁴C only in the phloem is needed as well; 'supports' rather than 'proves'", marks: 1 }], model: "The experiment supports the idea, because removing the bark stops sugars passing the ring, so they accumulate above it, while the xylem in the wood is intact and the leaves do not wilt. But the bark removed contains other tissues as well as phloem, so ringing alone cannot show which tissue carries the sugars. Autoradiographs after ¹⁴CO₂ feeding, which show the label only in the phloem, are needed too. So the results support the claim but do not prove it.", commonErrors: "Agreeing without considering other tissues in the bark." },
      // ---- extended ----
      { id: `q-${R}-e1`, ref: R, stmts: S(1, 2), type: "extended", marks: 6, stem: "Extended response. Describe the mass flow hypothesis for translocation in plants, and evaluate the evidence for it. (6 marks)", scheme: [{ point: "Sucrose actively loaded at the source by companion cells (ATP; co-transport with H⁺, supporting)", marks: 1 }, { point: "Water potential of the sap falls; water enters by osmosis from the xylem; hydrostatic pressure rises", marks: 1 }, { point: "At the sink sucrose is unloaded and used in respiration or stored as starch; water potential rises, water leaves, pressure lower", marks: 1 }, { point: "Mass flow of the solution along the sieve tubes (through sieve plates) from high to low pressure", marks: 1 }, { point: "Evidence for: aphid stylets show sap under pressure / concentration gradient; ringing; ¹⁴C tracers and autoradiographs show organic substances in the phloem; inhibitors at the source stop translocation (two needed)", marks: 1 }, { point: "Evaluation: sieve plates resist flow / different solutes at different speeds / two-way movement only if in different sieve tubes; so it is a hypothesis that is supported, not proved", marks: 1 }], levels: "Level 3 (5–6): the hypothesis described in the correct order with source and sink clearly distinguished, pressure and water potential used correctly, at least two pieces of evidence each linked to a part of the model, and at least one limitation weighed. Level 2 (3–4): most steps described, with some evidence but weak links or evaluation. Level 1 (1–2): a few relevant points without a clear sequence.", model: "At a source such as a mature leaf, companion cells use ATP to load sucrose actively into the sieve tube elements, for example by co-transport with hydrogen ions. This lowers the water potential of the sap, so water enters by osmosis from the xylem, raising the hydrostatic pressure. At a sink such as a root, sucrose is unloaded and used in respiration or converted to starch, so the water potential of the sap rises, water leaves by osmosis and the pressure stays lower. The solution therefore flows by mass flow along the sieve tubes, through the sieve plates, from high to low pressure. Evidence: sap oozes from cut aphid stylets, showing it is under pressure, and stylet sap is more concentrated near sources than near sinks; ringing a stem makes sugars build up above the ring; ¹⁴C from a leaf given ¹⁴CO₂ appears in the phloem on autoradiographs and reaches sinks; and metabolic inhibitors at the source stop translocation, showing loading is active. However, sieve plates should resist mass flow, different solutes sometimes move at different speeds, and substances can move both ways at once, which mass flow explains only if the flows are in different sieve tubes. So the hypothesis is well supported but may not be the whole explanation.", commonErrors: "Calling translocation active transport throughout; confusing water potential and hydrostatic pressure; listing evidence without saying what it shows." },
      { id: `q-${R}-e2`, ref: R, stmts: S(2), type: "extended", marks: 6, stem: "Extended response. Describe and explain how you could use experiments to show that water moves in the xylem while sucrose moves in the phloem. For each experiment, say what result you would expect and what it shows. (6 marks)", scheme: [{ point: "Dye experiment: cut shoot in dye, sections show dye only in the xylem", marks: 1 }, { point: "Ringing experiment: remove bark (phloem), leave xylem; leaves do not wilt, so water moves in the xylem", marks: 1 }, { point: "and sugars accumulate / bark swells above the ring, roots starve: sucrose moves in the phloem", marks: 1 }, { point: "¹⁴CO₂ supplied to a leaf; ¹⁴C fixed in sugars; autoradiograph of stem section dark only over the phloem", marks: 1 }, { point: "Aphid stylet: sap from a sieve tube analysed, shown to contain sucrose; exudes under pressure", marks: 1 }, { point: "Control (unringed plants / unlabelled leaf) and repeats; conclusions as support, not proof (bark has other tissues; dye may stain other cells if left too long)", marks: 1 }], levels: "Level 3 (5–6): at least three experiments clearly described, each with an expected result linked to the correct tissue, with controls or limitations considered. Level 2 (3–4): two experiments with expected results, some links to tissues. Level 1 (1–2): experiments named with little description or explanation.", model: "First, stand a leafy shoot, cut under water, in a dilute dye. After some time, cut thin cross-sections: only the xylem is stained, showing water moves up in the xylem. Second, remove a ring of bark, which contains the phloem, from the stems of several woody plants, leaving the wood, and compare with unringed controls. The leaves do not wilt, so water still moves up in the xylem; but over a few weeks sugars build up in the bark above the ring, which swells, while the roots receive none, so sucrose moves down in the phloem. Third, give one leaf ¹⁴CO₂ in the light; photosynthesis fixes the ¹⁴C into sugars. Place a section of the stem below on photographic film: it darkens only over the phloem, showing organic substances are carried there. Fourth, use the cut stylets of feeding aphids to collect sieve tube sap; it is mostly sucrose, and it oozes out under pressure. Each experiment needs controls and repeats, and each supports rather than proves the conclusion: for example the bark also contains cortex.", commonErrors: "Describing only phloem experiments; giving results without saying which tissue they implicate." },
    ],
  };
})();
